import ctypes
from types import SimpleNamespace

HEADER = """// compression.h
#include <stdint.h>

int32_t compress_block(const uint8_t *input, size_t length, uint8_t *output, size_t capacity);
const char *version(void);
void free_rect(struct rect *r);
double scale(double value, float factor);
"""

@test("the generated text")
def _():
    check_eq(generate_bindings(HEADER), "\n".join([
        "lib.compress_block.argtypes = [ctypes.POINTER(ctypes.c_uint8), ctypes.c_size_t, ctypes.POINTER(ctypes.c_uint8), ctypes.c_size_t]",
        "lib.compress_block.restype = ctypes.c_int32",
        "lib.version.argtypes = []",
        "lib.version.restype = ctypes.c_char_p",
        "lib.free_rect.argtypes = [ctypes.POINTER(rect)]",
        "lib.free_rect.restype = None",
        "lib.scale.argtypes = [ctypes.c_double, ctypes.c_float]",
        "lib.scale.restype = ctypes.c_double",
    ]))

@test("the text runs and sets real types")
def _():
    class rect(ctypes.Structure):
        _fields_ = [("w", ctypes.c_int), ("h", ctypes.c_int)]
    names = ["compress_block", "version", "free_rect", "scale"]
    mylib = SimpleNamespace(**{n: SimpleNamespace() for n in names})
    exec(generate_bindings(HEADER, lib="mylib"), {"ctypes": ctypes, "mylib": mylib, "rect": rect})
    check(mylib.compress_block.argtypes[0] is ctypes.POINTER(ctypes.c_uint8))
    check(mylib.compress_block.restype is ctypes.c_int32)
    check(mylib.version.restype is ctypes.c_char_p)
    check(mylib.free_rect.argtypes[0] is ctypes.POINTER(rect))
    check(mylib.free_rect.restype is None)

@test("errors name the line")
def _():
    try:
        generate_bindings("int ok(void);\n\nlong bad(long x);\n")
        check(False, "expected ValueError")
    except ValueError as e:
        check("line 3" in str(e), str(e))
    check_eq(generate_bindings("// nothing here\n\n#pragma once\n"), "")

